    return out.stdout if binary else out.stdout.decode('utf-8', 'replace')

TEST_DIRS = ['tests', 'compiler_tests', 'library_tests', 'other_compiler_tests', 'parser_tests',
             'syntax_abstraction_tests', 'not_passing_yet', 'not_working_static_tests', 'test_library',
             'not_working_library_tests', 'long_term_not_working', 'linker_tests',
             'not_working_compiler_tests', 'compiler_regressions', 'obsolete_interpreter_tests',
             'static_tests', 'shelltests', 'demos']
COORD = {'explorations/coordinator/FACTS.md', 'explorations/coordinator/POSITIONS.md',
         'explorations/coordinator/PLAN.md', 'explorations/coordinator/INDEX.md',
         'explorations/fortress-gap-ledger.md', 'explorations/microgpt-run-c-handover.md'}
CAPT = {'.txt', '.tsv', '.out', '.log', '.csv', '.json'}
PROBE = {'.fss', '.fsi', '.test'}
SCRIPT = {'.sh', '.py', '.js', '.java', '.scala', '.awk', '.sed', '.pl', '.rb', '.mjs', '.ts'}

def category(p):
    if p.startswith('Library/') or p.startswith('ProjectFortress/LibraryBuiltin/'):
        return 'CODE-lib'
    if p.startswith('ProjectFortress/src/'):
        if p.endswith('.java'): return 'CODE-java'
        if p.endswith('.scala'): return 'CODE-scala'
        return 'CODE-other'
    if p.startswith('ProjectFortress/astgen/') or os.path.basename(p) in ('build.xml', 'ant', 'build.properties'):
        return 'CODE-build'
    if p.startswith('Specification/'):
        if p == 'Specification/fortress.pdf': return 'SPEC-pdf'
        if p.endswith('.tex'): return 'SPEC-tex'
        return 'SPEC-other'
    parts = p.split('/')
    if parts[0] == 'ProjectFortress' and len(parts) > 2 and parts[1] in TEST_DIRS:
        return 'TESTS'
    if p in COORD:
        return 'COORD'
    if p.startswith('explorations/'):
        ext = os.path.splitext(p)[1].lower()
        if ext == '.md': return 'REC-REPORTS'
        if ext in CAPT: return 'REC-CAPTURES'
        if ext in PROBE: return 'REC-PROBES'
        if ext in SCRIPT: return 'REC-SCRIPTS'
        return 'REC-OTHER'
    return 'OTHER-tree'

def blob_size(commit, path):
    out = subprocess.run(['git', '-C', REPO, 'cat-file', '-s', f'{commit}:{path}'], capture_output=True)
    if out.returncode != 0: return None
    return int(out.stdout)

