            i += 1; continue
        a, d, rest = tok.split('\t', 2)
        if rest == '':
            old = stat[i+1].decode(); new = stat[i+2].decode(); i += 3
        else:
            old = new = rest; i += 1
        nums.append((None if a == '-' else int(a), None if d == '-' else int(d), old, new))
    st = []
    for line in ns:
        if not line: continue
        f = line.split('\t')
        s = f[0][0]
        if s == 'R':
            st.append((s, f[1], f[2]))
        else:
            st.append((s, f[1], f[1]))
    assert len(st) == len(nums), (c, len(st), len(nums))
    res = []
    for (s, o, n), (a, d, o2, n2) in zip(st, nums):
        assert n == n2, (c, n, n2)
        res.append(dict(status=s, old=o, new=n, add=a, dele=d))
    return res

