            sz_before = blob_size(par, o) if s != 'A' else 0
            row = dict(commit=c, status=s, old=o, new=n, add=f['add'], dele=f['dele'],
                       cat=category(n), promo=promo, spurious=spurious,
                       bytes_delta=(sz_after or 0) - (sz_before or 0), size_after=sz_after)
            if spurious:
                # count as delete of old + add of new
                la = blob_lines(c, n); lb = blob_lines(par, o)
                per.append(dict(row, status='D', new=o, cat=category(o), add=0, dele=lb, bytes_delta=-(sz_before or 0), size_after=0))
