import json, sys, collections, os, re, subprocess
D = '/tmp/claude-0/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/scratchpad/characterize/batch-7C-6.5'
REPO = '/home/user/fortress'
name, landing = sys.argv[1], sys.argv[2]
j = json.load(open(f'{D}/{name}.json'))
per, net = j['per'], j['net']

def exists_at(c, p):
    return subprocess.run(['git', '-C', REPO, 'cat-file', '-e', f'{c}:{p}'], capture_output=True).returncode == 0
def lines_at(c, p):
    out = subprocess.run(['git', '-C', REPO, 'show', f'{c}:{p}'], capture_output=True)
    return out.stdout.count(b'\n') if out.returncode == 0 else None
def size_at(c, p):
    out = subprocess.run(['git', '-C', REPO, 'cat-file', '-s', f'{c}:{p}'], capture_output=True)
    return int(out.stdout) if out.returncode == 0 else None

cat = collections.defaultdict(lambda: dict(paths=set(), add=0, dele=0, bytes=0, binary=0))
for r in per:
    c = cat[r['cat']]
    c['paths'].add(r['new'])
    if r['add'] is None:
        c['binary'] += 1
    else:
        c['add'] += r['add']; c['dele'] += r['dele']
    c['bytes'] += r['bytes_delta']
print('== by category (sum over commits): files, +, -, net bytes delta, binary changes')
for k in sorted(cat):
    c = cat[k]
    print(f"{k:14s} files={len(c['paths']):4d} +{c['add']:6d} -{c['dele']:6d} bytesdelta={c['bytes']:9d} binary={c['binary']}")

# per-commit per-category
print('== per commit')
pc = collections.defaultdict(lambda: collections.defaultdict(lambda: [0,0,0]))
for r in per:
    x = pc[r['commit']][r['cat']]
    x[0] += 1; x[1] += r['add'] or 0; x[2] += r['dele'] or 0
for cmt in dict.fromkeys(r['commit'] for r in per):
    print(cmt, ' '.join(f"{k}:{v[0]}f+{v[1]}-{v[2]}" for k, v in sorted(pc[cmt].items())))

# per-file code/spec
print('== CODE/SPEC files')
for r in per:
    if r['cat'].startswith('CODE') or r['cat'].startswith('SPEC'):
        print(r['commit'], r['status'], r['new'], r['add'], r['dele'], r['bytes_delta'], r['size_after'])

# TESTS
print('== TESTS')
tests = [r for r in per if r['cat'] == 'TESTS' or (r['status']=='R' and r['old'].startswith('ProjectFortress/') and '/tests' in r['old'])]
tnet = {p: s for p, s in net.items() if p.startswith('ProjectFortress/')}
def rung(p):
    return bool(re.search(r'(Rung[A-Z0-9]+|Repair(R\d+)?|Batch\d)', os.path.basename(p)))
groups = collections.defaultdict(list)
for p, s in sorted(tnet.items()):
    b = os.path.basename(p)
    if s == 'A':
        groups['newXXX' if b.startswith('XXX') else 'newplain'].append(p)
    elif s == 'P':
        groups['promoted'].append(p)
    elif s == 'Rgone':
        groups['promoted_from'].append(p)
    elif s == 'M':
        groups['modified'].append(p)
    elif s in ('D', 'MD'):
        groups['deleted'].append(p)
    elif s == 'AD':
        groups['added_then_deleted'].append(p)
    else:
        groups['other:' + s].append(p)
tadd = sum(r['add'] or 0 for r in per if r['cat'] == 'TESTS')
tdel = sum(r['dele'] or 0 for r in per if r['cat'] == 'TESTS')
print('test lines +', tadd, '-', tdel)
for g, ps in groups.items():
    ex = collections.Counter(os.path.splitext(p)[1] for p in ps)
    print(g, len(ps), dict(ex), 'rung-suffixed', sum(rung(p) for p in ps))
    # lines for group
    la = sum((r['add'] or 0) for r in per if r['new'] in ps and r['cat']=='TESTS')
    ld = sum((r['dele'] or 0) for r in per if r['new'] in ps and r['cat']=='TESTS')
    print('   lines +', la, '-', ld)
    if g in ('promoted', 'deleted', 'modified', 'promoted_from', 'added_then_deleted') or g.startswith('other'):
        for p in ps: print('    ', p)
newt = [p for p in groups['newplain'] + groups['newXXX']]
sized = sorted(((lines_at(landing, p) or 0, p) for p in newt), reverse=True)[:5]
print('largest new tests', sized)
print('all new names rung-suffixed:', sum(rung(p) for p in newt), 'of', len(newt))
print('new test programs (.fss):', sum(p.endswith('.fss') for p in newt), ' .test:', sum(p.endswith('.test') for p in newt))

# COORD
print('== COORD per file')
co = collections.defaultdict(lambda: [0, 0])
for r in per:
    if r['cat'] == 'COORD':
        co[r['new']][0] += r['add']; co[r['new']][1] += r['dele']
for p, v in sorted(co.items()): print(p, '+', v[0], '-', v[1])

# OTHER-tree
print('== OTHER-tree / SPEC-other / CODE-other')
for r in per:
    if r['cat'] in ('OTHER-tree', 'SPEC-other', 'CODE-other', 'CODE-build'):
        print(r['commit'], r['status'], r['new'], r['add'], r['dele'])

